const items = $input.all();

if (items.length !== 1) {
  throw new Error(`Expected one planner input item, received ${items.length}.`);
}

const input = items[0].json;

// Supports both shapes:
// 1) { planning_context, availability_facts }
// 2) raw planning context directly
const context = input.planning_context ?? input;
const facts = input.availability_facts ?? {};

const staff = Array.isArray(context.staff) ? context.staff : [];
const shifts = Array.isArray(context.shifts) ? context.shifts : [];
const availabilityDays = Array.isArray(context.availability_days)
  ? context.availability_days
  : [];
const training = Array.isArray(context.training) ? context.training : [];
const contracts = Array.isArray(context.contracts) ? context.contracts : [];
const submissions = Array.isArray(context.availability_submissions)
  ? context.availability_submissions
  : [];

function asDate(value) {
  if (!value) return null;
  const date = new Date(`${value}T00:00:00`);
  return Number.isNaN(date.getTime()) ? null : date;
}

function addDays(dateString, amount) {
  const date = asDate(dateString);
  if (!date) return null;
  date.setDate(date.getDate() + amount);
  return date.toISOString().slice(0, 10);
}

function isWeekend(dateString) {
  const date = asDate(dateString);
  if (!date) return false;
  const day = date.getDay();
  return day === 0 || day === 6;
}

function isSaturday(dateString) {
  const date = asDate(dateString);
  return date ? date.getDay() === 6 : false;
}

function isSunday(dateString) {
  const date = asDate(dateString);
  return date ? date.getDay() === 0 : false;
}

function staffName(person) {
  return person.full_name || person.name || person.email || person.id;
}

function workRole(person) {
  return person.work_role || person.role || null;
}

function schedulingRuleRole(person) {
  return person.scheduling_rule_role || person.work_role || person.role || null;
}

function getNumber(...values) {
  for (const value of values) {
    if (value === null || value === undefined || value === "") continue;
    const number = Number(value);
    if (Number.isFinite(number)) return number;
  }
  return null;
}

function getBool(value) {
  return value === true || value === "true" || value === 1 || value === "1";
}

function getAvailability(day, shiftType) {
  if (!day) return false;

  if (shiftType === "morning") {
    return getBool(day.morning ?? day.available_morning ?? day.morning_available);
  }

  if (shiftType === "day") {
    return getBool(day.day ?? day.available_day ?? day.day_available);
  }

  if (shiftType === "evening") {
    return getBool(day.evening ?? day.available_evening ?? day.evening_available);
  }

  return false;
}

function trainingForStaff(staffId) {
  return training.find((row) => row.staff_id === staffId) || {};
}

function contractForStaff(staffId) {
  return contracts.find((row) => row.staff_id === staffId) || {};
}

function submissionForStaff(staffId) {
  return submissions.find((row) => row.staff_id === staffId) || {};
}

function trainingPhase(staffId) {
  return (
    trainingForStaff(staffId).training_phase ||
    trainingForStaff(staffId).phase ||
    "phase_3_fully_trained"
  );
}

function canWorkIndependently(staffId, shiftType) {
  const phase = trainingPhase(staffId);

  if (phase === "phase_3_fully_trained") return true;

  if (
    phase === "phase_2_opening_independent" &&
    shiftType === "morning"
  ) {
    return true;
  }

  return false;
}

function periodWeekCount() {
  const period = context.period || {};
  const start = asDate(period.start_date);
  const end = asDate(period.end_date);

  if (!start || !end) return 4;

  const days = Math.max(
    1,
    Math.round((end.getTime() - start.getTime()) / 86400000) + 1
  );

  return Math.max(1, Math.ceil(days / 7));
}

function periodTarget(staffId) {
  const contract = contractForStaff(staffId);

  const weeklyTarget = getNumber(
    contract.target_shifts_per_week,
    contract.weekly_target_shifts,
    contract.target_weekly_shifts,
    contract.target
  );

  return weeklyTarget === null ? null : weeklyTarget * periodWeekCount();
}

function periodMax(staffId) {
  const contract = contractForStaff(staffId);

  const weeklyMax = getNumber(
    contract.max_shifts_per_week,
    contract.weekly_max_shifts,
    contract.max_weekly_shifts,
    contract.max
  );

  return weeklyMax === null ? null : weeklyMax * periodWeekCount();
}

function extraAllowance(staffId) {
  const submission = submissionForStaff(staffId);

  if (!submission.willing_to_work_above_target) return 0;

  return getNumber(
    submission.max_extra_shifts_for_period,
    submission.max_extra_shifts
  ) ?? 0;
}

const availabilityByStaffDate = new Map();

for (const day of availabilityDays) {
  availabilityByStaffDate.set(`${day.staff_id}:${day.available_date}`, day);
}

const assignedCountByStaff = new Map();
const assignedShiftByStaffDate = new Map();
const assignedDatesByStaff = new Map();

for (const person of staff) {
  assignedCountByStaff.set(person.id, 0);
  assignedDatesByStaff.set(person.id, new Set());
}

function hasSameDayAssignment(staffId, date) {
  return assignedShiftByStaffDate.has(`${staffId}:${date}`);
}

function hasEveningBeforeMorning(staffId, date, shiftType) {
  if (shiftType !== "morning") return false;

  const previousDate = addDays(date, -1);
  if (!previousDate) return false;

  return assignedShiftByStaffDate.get(`${staffId}:${previousDate}`) === "evening";
}

function wouldGiveCoreTeamFullWeekend(person, date) {
  if (!isWeekend(date)) return false;
  if (schedulingRuleRole(person) !== "core_team") return false;

  const pairedDate = isSaturday(date)
    ? addDays(date, 1)
    : isSunday(date)
      ? addDays(date, -1)
      : null;

  if (!pairedDate) return false;

  return assignedShiftByStaffDate.has(`${person.id}:${pairedDate}`);
}

function wouldExceedFiveConsecutiveDays(staffId, date) {
  const dates = new Set(assignedDatesByStaff.get(staffId) || []);
  dates.add(date);

  let maxRun = 0;

  for (const currentDate of dates) {
    let run = 1;

    let previous = addDays(currentDate, -1);
    while (previous && dates.has(previous)) {
      run += 1;
      previous = addDays(previous, -1);
    }

    let next = addDays(currentDate, 1);
    while (next && dates.has(next)) {
      run += 1;
      next = addDays(next, 1);
    }

    maxRun = Math.max(maxRun, run);
  }

  return maxRun > 5;
}

function scoreCandidate(person, shift) {
  const count = assignedCountByStaff.get(person.id) || 0;
  let score = count * 10;

  if (
    workRole(person) === "host" &&
    (shift.shift_type === "evening" || isWeekend(shift.shift_date))
  ) {
    score -= 8;
  }

  if (
    workRole(person) === "core_team" &&
    !isWeekend(shift.shift_date) &&
    shift.shift_type === "morning"
  ) {
    score -= 5;
  }

  if (
    staffName(person).toLowerCase().includes("haylin") &&
    isWeekend(shift.shift_date)
  ) {
    score += 100;
  }

  if (schedulingRuleRole(person) === "core_team" && isWeekend(shift.shift_date)) {
    score += 15;
  }

  return score;
}

function eligibleCandidatesForShift(shift) {
  return staff
    .filter((person) => {
      const staffId = person.id;
      const date = shift.shift_date;
      const shiftType = shift.shift_type;

      const availability = availabilityByStaffDate.get(`${staffId}:${date}`);

      if (!getAvailability(availability, shiftType)) return false;
      if (!canWorkIndependently(staffId, shiftType)) return false;
      if (hasSameDayAssignment(staffId, date)) return false;
      if (hasEveningBeforeMorning(staffId, date, shiftType)) return false;
      if (wouldGiveCoreTeamFullWeekend(person, date)) return false;
      if (wouldExceedFiveConsecutiveDays(staffId, date)) return false;

      const currentCount = assignedCountByStaff.get(staffId) || 0;
      const target = periodTarget(staffId);
      const max = periodMax(staffId);
      const extra = extraAllowance(staffId);

      if (max !== null && currentCount >= max) return false;
      if (target !== null && currentCount >= target + extra) return false;

      return true;
    })
    .sort((a, b) => {
      const scoreA = scoreCandidate(a, shift);
      const scoreB = scoreCandidate(b, shift);

      if (scoreA !== scoreB) return scoreA - scoreB;

      return staffName(a).localeCompare(staffName(b));
    });
}

function markAssigned(person, shift) {
  assignedCountByStaff.set(
    person.id,
    (assignedCountByStaff.get(person.id) || 0) + 1
  );

  assignedShiftByStaffDate.set(
    `${person.id}:${shift.shift_date}`,
    shift.shift_type
  );

  assignedDatesByStaff.get(person.id)?.add(shift.shift_date);
}

const shiftOrder = {
  morning: 1,
  day: 2,
  evening: 3,
};

const sortedShifts = [...shifts].sort((a, b) => {
  const dateCompare = String(a.shift_date || "").localeCompare(
    String(b.shift_date || "")
  );

  if (dateCompare !== 0) return dateCompare;

  return (shiftOrder[a.shift_type] || 99) - (shiftOrder[b.shift_type] || 99);
});

const assignments = [];
const unfilledShifts = [];

for (const shift of sortedShifts) {
  const requiredCount = getNumber(shift.required_count) ?? 1;
  const candidates = eligibleCandidatesForShift(shift);

  let assignedForShift = 0;

  while (assignedForShift < requiredCount && candidates.length > 0) {
    const person = candidates.shift();

    markAssigned(person, shift);
    assignedForShift += 1;

    assignments.push({
      shift_id: shift.id,
      shift_date: shift.shift_date,
      shift_type: shift.shift_type,
      staff_id: person.id,
      staff_name: staffName(person),
      work_role: workRole(person),
      scheduling_rule_role: schedulingRuleRole(person),
      training_phase: trainingPhase(person.id),
      assignment_kind: "coverage",
      source: "planner_engine_v0",
      reason:
        "Selected by deterministic planner using availability, training phase, workload balance, and hard-rule filters."
    });
  }

  if (assignedForShift < requiredCount) {
    unfilledShifts.push({
      shift_id: shift.id,
      shift_date: shift.shift_date,
      shift_type: shift.shift_type,
      required_count: requiredCount,
      assigned_count: assignedForShift,
      missing_count: requiredCount - assignedForShift,
      reason:
        "Not enough eligible staff after applying availability, training, workload, weekend, rest, and target filters."
    });
  }
}

const staffLoadSummary = staff.map((person) => ({
  staff_id: person.id,
  staff_name: staffName(person),
  work_role: workRole(person),
  scheduling_rule_role: schedulingRuleRole(person),
  training_phase: trainingPhase(person.id),
  assigned_shift_count: assignedCountByStaff.get(person.id) || 0,
  period_target_shifts: periodTarget(person.id),
  period_max_shifts: periodMax(person.id),
  extra_shift_allowance: extraAllowance(person.id)
}));

return [
  {
    json: {
      ...input,
      planning_context: context,
      availability_facts: facts,
      draft_plan: {
        planner_version: "planner_engine_v0",
        generated_at: new Date().toISOString(),
        assignments,
        unfilled_shifts: unfilledShifts,
        staff_load_summary: staffLoadSummary,
        planner_notes: [
          "Draft generated by deterministic Planner Engine v0.",
          "Phase 1 trainees are not assigned as independent coverage.",
          "Budget optimization and trainee shadow scheduling are not included in v0.",
          "Draft must still pass Workflow 04 validation before being committed."
        ]
      }
    }
  }
];

const items = $input.all();

if (items.length !== 1) {
  throw new Error(`Expected one planner item, received ${items.length}.`);
}

const payload = items[0].json;

const context = payload.planning_context;
const facts = payload.availability_facts;
const draftPlan = payload.draft_plan;

if (!context || typeof context !== "object") {
  throw new Error("Missing planning_context.");
}

if (!facts || typeof facts !== "object") {
  throw new Error("Missing availability_facts.");
}

if (!draftPlan || typeof draftPlan !== "object") {
  throw new Error("Missing draft_plan.");
}

const staff = Array.isArray(context.staff) ? context.staff : [];
const training = Array.isArray(context.training) ? context.training : [];
const contracts = Array.isArray(context.contracts) ? context.contracts : [];

function staffName(person) {
  return person.full_name || person.name || person.display_name || person.email || person.id;
}

function trainingForStaff(staffId) {
  return training.find((row) => row.staff_id === staffId) || {};
}

function contractForStaff(staffId) {
  return contracts.find((row) => row.staff_id === staffId) || {};
}

const staffSummary = staff.map((person) => {
  const load = Array.isArray(draftPlan.staff_load_summary)
    ? draftPlan.staff_load_summary.find((row) => row.staff_id === person.id) || {}
    : {};

  const trainingRow = trainingForStaff(person.id);
  const contract = contractForStaff(person.id);

  return {
    staff_id: person.id,
    name: staffName(person),
    work_role: person.work_role || person.role || null,
    scheduling_rule_role:
      person.scheduling_rule_role ||
      person.schedulingRuleRole ||
      person.work_role ||
      person.role ||
      null,
    training_phase:
      trainingRow.training_phase ||
      trainingRow.phase ||
      load.training_phase ||
      null,
    assigned_shift_count: load.assigned_shift_count ?? 0,
    period_target_shifts: load.period_target_shifts ?? null,
    period_max_shifts: load.period_max_shifts ?? null,
    extra_shift_allowance: load.extra_shift_allowance ?? 0,
    weekly_min_shifts:
      contract.min_shifts_per_week ||
      contract.weekly_min_shifts ||
      contract.min_weekly_shifts ||
      null,
    weekly_target_shifts:
      contract.target_shifts_per_week ||
      contract.weekly_target_shifts ||
      contract.target_weekly_shifts ||
      null,
    weekly_max_shifts:
      contract.max_shifts_per_week ||
      contract.weekly_max_shifts ||
      contract.max_weekly_shifts ||
      null,
  };
});

const assignmentSummary = Array.isArray(draftPlan.assignments)
  ? draftPlan.assignments.map((assignment) => ({
      shift_id: assignment.shift_id,
      shift_date: assignment.shift_date,
      shift_type: assignment.shift_type,
      staff_id: assignment.staff_id,
      staff_name: assignment.staff_name,
      work_role: assignment.work_role,
      scheduling_rule_role: assignment.scheduling_rule_role,
      training_phase: assignment.training_phase,
    }))
  : [];

const reviewPacket = {
  generation_run_id: payload.generation_run_id,
  period_id: payload.period_id,

  period: context.period || null,

  hard_rules_summary: [
    "Do not assign staff when unavailable.",
    "Do not assign Phase 1 trainees as independent coverage.",
    "Phase 2 staff may open/morning independently but should not close/evening alone.",
    "Do not assign the same staff member twice on the same day.",
    "Do not assign evening followed by next morning.",
    "Do not exceed max shifts.",
    "Do not assign above target unless staff consented through availability submission.",
    "Core Team should not work both Saturday and Sunday in the same weekend.",
    "Haylin should avoid weekends unless absolutely necessary.",
    "Lilly consumes Host budget but follows Core Team scheduling rules.",
  ],

  diagnostics: context.diagnostics || {},

  staff_summary: staffSummary,

  scarce_shifts: facts.scarce_shifts || [],

  unfilled_shifts: draftPlan.unfilled_shifts || [],

  staff_load_summary: draftPlan.staff_load_summary || [],

  assignment_summary: assignmentSummary,

  planner_notes: draftPlan.planner_notes || [],
};

return [
  {
    json: {
      ...payload,
      planner_agent_input: reviewPacket,
    },
  },
];

const item = $input.first().json;

if (!item.planner_agent_input) {
  throw new Error("Missing planner_agent_input before Planner Agent Review.");
}

if (!Array.isArray(item.planner_agent_input.staff_summary)) {
  throw new Error("planner_agent_input.staff_summary is missing.");
}

if (!Array.isArray(item.planner_agent_input.assignment_summary)) {
  throw new Error("planner_agent_input.assignment_summary is missing.");
}

return [$input.first()];

const items = $input.all();

if (items.length !== 1) {
  throw new Error(`Expected one planner agent review item, received ${items.length}.`);
}

// This is the full payload from before the AI agent.
// It contains generation_run_id, period_id, planning_context, availability_facts,
// draft_plan, planner_agent_input, planner_agent_prompt, etc.
const previous = $('Build Planner Agent Prompt').item.json;

// This is the AI Agent output.
// Usually shaped like: { output: "{...json string...}" }
const current = items[0].json;

let raw =
  current.output ??
  current.text ??
  current.response ??
  current.message ??
  current.result ??
  current;

let review;

// If n8n/model already returned an object, use it directly.
if (raw && typeof raw === "object" && !Array.isArray(raw)) {
  review = raw;
} else {
  if (typeof raw !== "string") {
    throw new Error(`Planner Agent Review returned unsupported output type: ${typeof raw}`);
  }

  raw = raw.trim();

  // Remove markdown code fences if the model adds them anyway.
  raw = raw
    .replace(/^```json\s*/i, "")
    .replace(/^```\s*/i, "")
    .replace(/```$/i, "")
    .trim();

  // Extract the first JSON object if accidental text appears around it.
  const firstBrace = raw.indexOf("{");
  const lastBrace = raw.lastIndexOf("}");

  if (firstBrace === -1 || lastBrace === -1 || lastBrace <= firstBrace) {
    throw new Error(`Planner Agent Review did not contain a JSON object. Raw output: ${raw}`);
  }

  const jsonText = raw.slice(firstBrace, lastBrace + 1);

  try {
    review = JSON.parse(jsonText);
  } catch (error) {
    throw new Error(
      `Could not parse Planner Agent Review JSON: ${error.message}. Raw output: ${raw}`
    );
  }
}

return [
  {
    json: {
      ...previous,
      planner_agent_review: review,
    },
  },
];

const items = $input.all();

if (items.length !== 1) {
  throw new Error(`Expected one packaged planner agent review item, received ${items.length}.`);
}

const payload = items[0].json;
const review = payload.planner_agent_review;

if (!review || typeof review !== "object" || Array.isArray(review)) {
  throw new Error("Missing planner_agent_review object.");
}

if (typeof review.agent_summary !== "string") {
  throw new Error("planner_agent_review.agent_summary must be a string.");
}

if (!["low", "medium", "high", "critical"].includes(review.overall_risk_level)) {
  throw new Error(
    `planner_agent_review.overall_risk_level is invalid: ${String(review.overall_risk_level)}`
  );
}

const requiredArrays = [
  "coverage_risks",
  "recommended_adjustments",
  "unfilled_shift_strategy",
  "fairness_notes",
  "training_notes",
  "human_review_flags",
];

for (const field of requiredArrays) {
  if (!Array.isArray(review[field])) {
    throw new Error(`planner_agent_review.${field} must be an array.`);
  }
}

for (const adjustment of review.recommended_adjustments) {
  if (adjustment.safe_to_auto_apply !== false) {
    throw new Error(
      "Planner agent recommended an auto-apply adjustment. This is not allowed in v0."
    );
  }
}

return items;

const items = $input.all();

if (items.length !== 1) {
  throw new Error(`Expected one draft plan item, received ${items.length}.`);
}

const originalPayload = items[0].json;

/**
 * The clean expected shape is:
 * {
 *   generation_run_id,
 *   period_id,
 *   planning_context: { context_version: 1, ... },
 *   availability_facts,
 *   draft_plan,
 *   planner_agent_review
 * }
 *
 * But during debugging, the object may have become nested like:
 * {
 *   planning_context: {
 *     generation_run_id,
 *     period_id,
 *     planning_context: { context_version: 1, ... }
 *   }
 * }
 *
 * This validation node normalizes that back into the clean shape.
 */

const wrapper =
  originalPayload.generation_run_id
    ? originalPayload
    : originalPayload.planning_context?.generation_run_id
      ? originalPayload.planning_context
      : originalPayload;

const generationRunId =
  originalPayload.generation_run_id ??
  wrapper.generation_run_id ??
  originalPayload.planning_context?.generation_run_id;

const periodId =
  originalPayload.period_id ??
  wrapper.period_id ??
  originalPayload.planning_context?.period_id ??
  wrapper.planning_context?.period_id ??
  wrapper.planning_context?.period?.id;

const actualPlanningContext =
  originalPayload.planning_context?.context_version === 1
    ? originalPayload.planning_context
    : wrapper.planning_context?.context_version === 1
      ? wrapper.planning_context
      : originalPayload.planning_context?.planning_context?.context_version === 1
        ? originalPayload.planning_context.planning_context
        : null;

const availabilityFacts =
  originalPayload.availability_facts ??
  wrapper.availability_facts ??
  originalPayload.planning_context?.availability_facts;

const draftPlan =
  originalPayload.draft_plan ??
  wrapper.draft_plan ??
  originalPayload.planning_context?.draft_plan;

const plannerAgentReview =
  originalPayload.planner_agent_review ??
  wrapper.planner_agent_review ??
  originalPayload.planning_context?.planner_agent_review;

if (!generationRunId) {
  throw new Error("Missing generation_run_id.");
}

if (!periodId) {
  throw new Error("Missing period_id.");
}

if (!actualPlanningContext || typeof actualPlanningContext !== "object") {
  throw new Error("Missing valid actual planning_context with context_version = 1.");
}

if (actualPlanningContext.context_version !== 1) {
  throw new Error(
    `Unsupported planning_context version: ${String(actualPlanningContext.context_version)}`
  );
}

if (!availabilityFacts || typeof availabilityFacts !== "object") {
  throw new Error("Missing availability_facts.");
}

if (!draftPlan || typeof draftPlan !== "object") {
  throw new Error("Missing draft_plan.");
}

if (!plannerAgentReview || typeof plannerAgentReview !== "object") {
  throw new Error("Missing planner_agent_review.");
}

if (typeof draftPlan.planner_version !== "string") {
  throw new Error("draft_plan.planner_version must be a string.");
}

if (typeof draftPlan.generated_at !== "string") {
  throw new Error("draft_plan.generated_at must be a string.");
}

const requiredDraftArrays = [
  "assignments",
  "unfilled_shifts",
  "staff_load_summary",
  "planner_notes",
];

for (const field of requiredDraftArrays) {
  if (!Array.isArray(draftPlan[field])) {
    throw new Error(`draft_plan.${field} must be an array.`);
  }
}

for (const assignment of draftPlan.assignments) {
  const requiredAssignmentFields = [
    "shift_id",
    "shift_date",
    "shift_type",
    "staff_id",
    "staff_name",
    "assignment_kind",
    "source",
  ];

  for (const field of requiredAssignmentFields) {
    if (!assignment[field]) {
      throw new Error(`Draft assignment is missing ${field}.`);
    }
  }

  if (!["morning", "day", "evening"].includes(assignment.shift_type)) {
    throw new Error(
      `Invalid assignment.shift_type: ${String(assignment.shift_type)}`
    );
  }
}

for (const unfilled of draftPlan.unfilled_shifts) {
  const requiredUnfilledFields = [
    "shift_id",
    "shift_date",
    "shift_type",
    "required_count",
    "assigned_count",
    "missing_count",
    "reason",
  ];

  for (const field of requiredUnfilledFields) {
    if (
      unfilled[field] === undefined ||
      unfilled[field] === null ||
      unfilled[field] === ""
    ) {
      throw new Error(`Unfilled shift is missing ${field}.`);
    }
  }

  if (!["morning", "day", "evening"].includes(unfilled.shift_type)) {
    throw new Error(
      `Invalid unfilled.shift_type: ${String(unfilled.shift_type)}`
    );
  }

  if (Number(unfilled.missing_count) <= 0) {
    throw new Error(
      `Unfilled shift ${unfilled.shift_id} has invalid missing_count.`
    );
  }
}

for (const load of draftPlan.staff_load_summary) {
  const requiredLoadFields = [
    "staff_id",
    "staff_name",
    "assigned_shift_count",
  ];

  for (const field of requiredLoadFields) {
    if (
      load[field] === undefined ||
      load[field] === null ||
      load[field] === ""
    ) {
      throw new Error(`Staff load summary row is missing ${field}.`);
    }
  }

  if (!Number.isFinite(Number(load.assigned_shift_count))) {
    throw new Error(
      `Invalid assigned_shift_count for staff ${load.staff_id}.`
    );
  }
}

const requiredReviewArrays = [
  "coverage_risks",
  "recommended_adjustments",
  "unfilled_shift_strategy",
  "fairness_notes",
  "training_notes",
  "human_review_flags",
];

if (typeof plannerAgentReview.agent_summary !== "string") {
  throw new Error("planner_agent_review.agent_summary must be a string.");
}

if (
  !["low", "medium", "high", "critical"].includes(
    plannerAgentReview.overall_risk_level
  )
) {
  throw new Error(
    `Invalid planner_agent_review.overall_risk_level: ${String(
      plannerAgentReview.overall_risk_level
    )}`
  );
}

for (const field of requiredReviewArrays) {
  if (!Array.isArray(plannerAgentReview[field])) {
    throw new Error(`planner_agent_review.${field} must be an array.`);
  }
}

/**
 * Return the clean, flat payload.
 * This prevents the bad nested shape from continuing downstream.
 */
return [
  {
    json: {
      generation_run_id: generationRunId,
      period_id: periodId,

      planning_context: actualPlanningContext,
      availability_facts: availabilityFacts,
      draft_plan: draftPlan,
      planner_agent_review: plannerAgentReview,

      draft_plan_shape_validated: true,
      planner_engine_completed_at: new Date().toISOString(),
    },
  },
];
